mapper.select:
select history.biz_id, history.biz_no, history.biz_type, history.warehouse_id, w.warehouse_name, history.after_quantity, history.before_quantity, history.quantity, history.unit_price, history.create_time, item.item_no, item.item_name, sku.id as sku_id, sku.sku_no, sku.sku_name from wms_inventory_history history left join wms_item_sku sku on history.sku_id=sku.id left join wms_item item on sku.item_id=item.id left join wms_warehouse w on history.warehouse_id=w.id
history.biz_type=#{dto.bizType}
and history.biz_no=#{dto.bizNo}
and item.item_name like concat('%', #{dto.itemName}, '%')
and item.item_no like concat('%', #{dto.itemNo}, '%')
and sku.sku_name like concat('%', #{dto.skuName}, '%')
and sku.id = #{dto.skuId}
and sku.sku_no like concat('%', #{dto.skuNo}, '%')
and history.warehouse_id=#{dto.warehouseId}
and (history.create_time between #{dto.startTime} and #{dto.endTime})
order by history.create_time desc
